 ## Unreleased

 - Faster tag lookup.
+- Fix days left counting UTC calendar days, so an item expiring tomorrow no longer shows 0 in the afternoon, and items are good through the end of their expiry date.

 ## 1.4.2 - 2026-09-30

diff --git a/src/expiry.js b/src/expiry.js
index 0a7b267..dd04691 100644
--- a/src/expiry.js
+++ b/src/expiry.js
@@ -2,9 +2,11 @@ import { log } from "./log.js";

 const DAY = 86400000;

-/** Whole days until the item expires (negative once expired). */
+/** UTC calendar days from `now` to the expiry date (negative once expired). */
 export function daysLeft(item, now = Date.now()) {
-  return Math.floor((Date.parse(item.expires) - now) / DAY);
+  const today = Math.floor(now / DAY);
+  const expiry = Math.floor(Date.parse(item.expires) / DAY);
+  return expiry - today;
 }

 /** True once the item has expired; logs a warning. */
@@ -14,5 +16,5 @@ export function isExpired(item, now = Date.now()) {
     log.warn("item expired", { id: item.id, days: left });
     return true;
   }
-  return left === 0;
+  return false;
 }
